-- CounterNest POS Phase 33.8: security review, retention policy, and recovery-drill evidence.
create table public.security_retention_settings(
  shop_id uuid primary key references public.shops(id) on delete cascade,audit_retention_years integer not null default 7 check(audit_retention_years between 1 and 20),
  sales_retention_years integer not null default 7 check(sales_retention_years between 1 and 20),customer_inactive_review_months integer not null default 24 check(customer_inactive_review_months between 6 and 120),
  backup_target_days integer not null default 7 check(backup_target_days between 1 and 31),automatic_purge_enabled boolean not null default false,
  updated_by uuid not null references auth.users(id) on delete restrict,updated_at timestamptz not null default now()
);
create table public.security_review_runs(
  id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,status text not null check(status in('passed','warning','failed')),
  checks jsonb not null,management_note text,run_by uuid not null references auth.users(id) on delete restrict,run_at timestamptz not null default now()
);
create table public.recovery_drill_records(
  id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,drill_date date not null,test_environment text not null,
  backup_filename text not null,sha256_verified boolean not null,restore_completed boolean not null,application_verified boolean not null,result text not null check(result in('passed','partial','failed')),
  evidence_note text not null,performed_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now()
);
create index security_review_runs_idx on public.security_review_runs(shop_id,run_at desc);create index recovery_drill_records_idx on public.recovery_drill_records(shop_id,drill_date desc);
alter table public.security_retention_settings enable row level security;alter table public.security_review_runs enable row level security;alter table public.recovery_drill_records enable row level security;
create policy security_retention_admin_read on public.security_retention_settings for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());
create policy security_review_admin_read on public.security_review_runs for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());
create policy recovery_drill_admin_read on public.recovery_drill_records for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

create or replace function public.save_security_retention_settings(p_audit_years integer,p_sales_years integer,p_customer_months integer,p_backup_days integer) returns void language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if p_audit_years not between 1 and 20 or p_sales_years not between 1 and 20 or p_customer_months not between 6 and 120 or p_backup_days not between 1 and 31 then raise exception 'Retention settings are outside allowed limits';end if;insert into public.security_retention_settings(shop_id,audit_retention_years,sales_retention_years,customer_inactive_review_months,backup_target_days,automatic_purge_enabled,updated_by) values(v_shop,p_audit_years,p_sales_years,p_customer_months,p_backup_days,false,auth.uid()) on conflict(shop_id) do update set audit_retention_years=excluded.audit_retention_years,sales_retention_years=excluded.sales_retention_years,customer_inactive_review_months=excluded.customer_inactive_review_months,backup_target_days=excluded.backup_target_days,automatic_purge_enabled=false,updated_by=auth.uid(),updated_at=now();end $$;

create or replace function public.run_security_review(p_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_checks jsonb;v_status text;v_id uuid;v_admins integer;v_inactive integer;v_backup_age integer;v_open_attendance integer;v_open_cash integer;
begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;
insert into public.security_retention_settings(shop_id,updated_by) values(v_shop,auth.uid()) on conflict(shop_id) do nothing;
select count(*) into v_admins from public.staff_profiles where shop_id=v_shop and active and role='admin';select count(*) into v_inactive from public.staff_profiles where shop_id=v_shop and not active;
select coalesce(current_date-max(requested_at::date),9999) into v_backup_age from public.backup_exports where shop_id=v_shop;
select count(*) into v_open_attendance from public.staff_attendance_entries where shop_id=v_shop and status='open' and clock_in_at<now()-interval '18 hours';select count(*) into v_open_cash from public.cash_drawer_sessions where shop_id=v_shop and status='open' and opened_at<now()-interval '24 hours';
v_checks:=jsonb_build_array(
 jsonb_build_object('key','active_admin','label','At least one active administrator','status',case when v_admins>0 then 'passed' else 'failed' end,'detail',v_admins||' active administrator(s)'),
 jsonb_build_object('key','recent_backup','label','Recent business backup','status',case when v_backup_age<=(select backup_target_days from public.security_retention_settings where shop_id=v_shop) then 'passed' else 'warning' end,'detail',case when v_backup_age=9999 then 'No backup export recorded' else v_backup_age||' day(s) since export' end),
 jsonb_build_object('key','long_attendance','label','No attendance entry open over 18 hours','status',case when v_open_attendance=0 then 'passed' else 'warning' end,'detail',v_open_attendance||' long-running entry(s)'),
 jsonb_build_object('key','stale_cash','label','No Daily Cash record open over 24 hours','status',case when v_open_cash=0 then 'passed' else 'failed' end,'detail',v_open_cash||' stale record(s)'),
 jsonb_build_object('key','inactive_staff','label','Inactive staff records retained for audit','status','passed','detail',v_inactive||' inactive staff record(s); authentication access should also be reviewed in Supabase')
);
v_status:=case when v_checks@>'[{"status":"failed"}]'::jsonb then 'failed' when v_checks@>'[{"status":"warning"}]'::jsonb then 'warning' else 'passed' end;
insert into public.security_review_runs(shop_id,status,checks,management_note,run_by) values(v_shop,v_status,v_checks,nullif(trim(p_note),''),auth.uid()) returning id into v_id;return jsonb_build_object('id',v_id,'status',v_status,'checks',v_checks,'run_at',now());end $$;

create or replace function public.record_recovery_drill(p_drill_date date,p_test_environment text,p_backup_filename text,p_sha256_verified boolean,p_restore_completed boolean,p_application_verified boolean,p_evidence_note text) returns uuid language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_result text;v_id uuid;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if p_drill_date is null or length(trim(coalesce(p_test_environment,'')))<3 or length(trim(coalesce(p_backup_filename,'')))<3 or length(trim(coalesce(p_evidence_note,'')))<10 then raise exception 'Complete recovery drill evidence is required';end if;if lower(p_test_environment) in('production','live') then raise exception 'Recovery drills must use a separate non-production environment';end if;v_result:=case when p_sha256_verified and p_restore_completed and p_application_verified then 'passed' when p_restore_completed or p_application_verified then 'partial' else 'failed' end;insert into public.recovery_drill_records(shop_id,drill_date,test_environment,backup_filename,sha256_verified,restore_completed,application_verified,result,evidence_note,performed_by) values(v_shop,p_drill_date,trim(p_test_environment),trim(p_backup_filename),p_sha256_verified,p_restore_completed,p_application_verified,v_result,trim(p_evidence_note),auth.uid()) returning id into v_id;return v_id;end $$;

create or replace function public.get_security_recovery_board() returns jsonb language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;insert into public.security_retention_settings(shop_id,updated_by) values(v_shop,auth.uid()) on conflict(shop_id) do nothing;return jsonb_build_object('settings',(select to_jsonb(s) from public.security_retention_settings s where shop_id=v_shop),'reviews',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'status',r.status,'checks',r.checks,'management_note',r.management_note,'run_at',r.run_at,'run_by_name',coalesce(sp.display_name,'Former staff')) order by r.run_at desc),'[]'::jsonb) from public.security_review_runs r left join public.staff_profiles sp on sp.shop_id=r.shop_id and sp.user_id=r.run_by where r.shop_id=v_shop limit 20),'drills',(select coalesce(jsonb_agg(to_jsonb(x) order by x.drill_date desc),'[]'::jsonb) from(select d.*,coalesce(sp.display_name,'Former staff') performed_by_name from public.recovery_drill_records d left join public.staff_profiles sp on sp.shop_id=d.shop_id and sp.user_id=d.performed_by where d.shop_id=v_shop order by d.drill_date desc limit 20)x));end $$;

alter function public.export_business_backup() rename to export_business_backup_phase337_base;revoke all on function public.export_business_backup_phase337_base() from public;revoke all on function public.export_business_backup_phase337_base() from authenticated;
create or replace function public.export_business_backup() returns jsonb language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_base jsonb;v_export uuid;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;v_base:=public.export_business_backup_phase337_base();v_export:=(v_base->>'export_id')::uuid;update public.backup_exports set schema_version='1.21.0' where id=v_export and shop_id=v_shop;return(v_base-'schema_version')||jsonb_build_object('schema_version','1.21.0','security_retention_settings',(select to_jsonb(t) from public.security_retention_settings t where shop_id=v_shop),'security_review_runs',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.security_review_runs t where shop_id=v_shop),'recovery_drill_records',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.recovery_drill_records t where shop_id=v_shop));end $$;
revoke all on function public.save_security_retention_settings(integer,integer,integer,integer) from public;revoke all on function public.run_security_review(text) from public;revoke all on function public.record_recovery_drill(date,text,text,boolean,boolean,boolean,text) from public;revoke all on function public.get_security_recovery_board() from public;revoke all on function public.export_business_backup() from public;
grant execute on function public.save_security_retention_settings(integer,integer,integer,integer) to authenticated;grant execute on function public.run_security_review(text) to authenticated;grant execute on function public.record_recovery_drill(date,text,text,boolean,boolean,boolean,text) to authenticated;grant execute on function public.get_security_recovery_board() to authenticated;grant execute on function public.export_business_backup() to authenticated;
